(function () {
"use strict";

// --- LÓGICA DO CRONÔMETRO ---
let timerInterval = null;
let seconds = 0;

function startTimer() {
if (!timerInterval) {
timerInterval = setInterval(() => {
seconds++;
const m = Math.floor(seconds / 60).toString().padStart(2, '0');
const s = (seconds % 60).toString().padStart(2, '0');
document.getElementById('crono-timer').textContent = `${m}:${s}`;
}, 1000);
}
}

// --- ESTRUTURA DE DADOS DOS CRITÉRIOS DE RASS (FATOR ÚNICO) ---
const ITENS_RASS = [
{
id: "nivelRass",
label: "1. Livello di Agitazione / Sedazione",
opts: [
{ val: "", text: "Seleziona il livello..." },
{ val: 4, text: "+4 - Molto agitato (Aggressivo/Pericoloso)" },
{ val: 3, text: "+3 - Agitato (Tira tubi/cateteri)" },
{ val: 2, text: "+2 - Molto irrequieto (Movimenti scoordinati)" },
{ val: 1, text: "+1 - Irrequieto (Ansioso, senza aggressività)" },
{ val: 0, text: " 0 - Vigile e calmo (Stato ideale)" },
{ val: -1, text: "-1 - Sonnolento (Contatto visivo sostenuto >10s)" },
{ val: -2, text: "-2 - Sedazione leggera (Contatto visivo breve <10s)" },
{ val: -3, text: "-3 - Sedazione moderata (Si muove senza contatto visivo)" },
{ val: -4, text: "-4 - Sedazione profonda (Reagisce solo a stimoli dolorosi)" },
{ val: -5, text: "-5 - Nessuna risposta (Nessuna risposta agli stimoli)" }
],
}
];

// --- RENDERIZAÇÃO DOS CARDS (GRID) ---
function renderizarItensRass() {
const container = document.getElementById("rassForm");
container.innerHTML = "";

ITENS_RASS.forEach((item) => {
let optsHtml = "";
item.opts.forEach((op) => {
optsHtml += `<option value="${op.val}" ${op.val === "" ? "disabled selected" : ""}>${op.text}</option>`;
});

const div = document.createElement("div");
div.className = "item-card";
div.id = `card_${item.id}`;
div.innerHTML = `
<div class="flex items-center justify-between mb-2">
<label for="${item.id}" class="text-[13px] font-bold text-slate-800">${item.label}</label>
<span id="badge_${item.id}" class="item-badge">--/Punteggio</span>
</div>
<p class="text-[11px] text-slate-500 mb-3 leading-snug h-8">Selezionare il livello clinico che descrive il paziente.</p>
<select id="${item.id}" class="item-select">${optsHtml}</select>
<div class="mini-bar-wrap">
<div id="bar_${item.id}" class="mini-bar-fill" style="width: 0%;"></div>
</div>
`;
container.appendChild(div);

const el = document.getElementById(item.id);
// Listener para atualizar card individual
el.addEventListener("change", () => {
document.getElementById(`card_${item.id}`).classList.remove("error");
document.getElementById("msgValidacaoErro").style.display = "none";
atualizarCardIndividual(item.id);
});

el.addEventListener('change', startTimer, {once: true});

// Evitar scroll acidental
el.addEventListener("wheel", function(e) { e.preventDefault(); this.blur(); });
});
}

// --- ATUALIZAR STATUS DE UM CARD ESPECÍFICO ---
function atualizarCardIndividual(id) {
const select = document.getElementById(id);
const valStr = select.value;
if (valStr === "") return;
const val = parseInt(valStr);
const pct = 100;

const badge = document.getElementById(`badge_${id}`);
const bar = document.getElementById(`bar_${id}`);

badge.textContent = `${val > 0 ? '+'+val : val}`;
bar.style.width = `${pct}%`;

// Cores baseadas na gravidade
let cor = "transparent";
if (val >= 3) cor = "#e11d48"; // Vermelho
else if (val >= 1) cor = "#ea580c"; // Laranja
else if (val === 0) cor = "#16a34a"; // Verde
else if (val >= -3) cor = "#eab308"; // Amarelo
else cor = "#e11d48"; // Vermelho (Coma)

bar.style.backgroundColor = cor;

// Badge também muda de cor conforme escore
badge.style.backgroundColor = cor === "transparent" ? "" : `${cor}15`;
badge.style.color = cor === "transparent" ? "" : cor;
badge.style.borderColor = cor === "transparent" ? "" : `${cor}30`;

atualizarBarraGlobal();
}

// --- BARRA FLUTUANTE GLOBAL E CONTADOR ---
function atualizarBarraGlobal() {
let preenchidos = 0;
ITENS_RASS.forEach((i) => {
if (document.getElementById(i.id).value !== "") preenchidos++;
});

const pctGlobal = (preenchidos / 1) * 100;
document.getElementById("progress-bar-global").style.width = `${pctGlobal}%`;
document.getElementById("contadorPreenchidos").textContent = `${preenchidos}/1`;
}

// --- LÓGICA DADOS DO PACIENTE (TOGGLE) ---
document.getElementById("btnToggleDados").addEventListener("click", function () {
const body = document.getElementById("dadosBody");
const chevron = document.getElementById("dadosChevron");
const subtitle = document.getElementById("dadosSubtitle");

if (body.classList.contains("open")) {
body.classList.remove("open");
chevron.style.transform = "rotate(0deg)";
subtitle.textContent = "Compila per la Cartella Clinica/Referto PDF";
this.style.background = "white";
} else {
body.classList.add("open");
chevron.style.transform = "rotate(180deg)";
subtitle.textContent = "Nascondi pannello";
this.style.background = "#EFF6FF";
}
});
document.getElementById("pacData").value = new Date().toISOString().split("T")[0];

// --- CÁLCULO E RESULTADO ---
const resultadoSection = document.getElementById("resultado-section");

function calcular() {
let incompleto = false;
let somaTotal = 0;
let dominiosValores = [];
let diagnosticosKeywords = [];
let primeiroErro = null;

ITENS_RASS.forEach((item) => {
const selectVal = document.getElementById(item.id).value;
if (selectVal === "") {
incompleto = true;
document.getElementById(`card_${item.id}`).classList.add("error");
if(!primeiroErro) primeiroErro = document.getElementById(`card_${item.id}`);
dominiosValores.push({ nome: item.label, obtido: 0 });
} else {
document.getElementById(`card_${item.id}`).classList.remove("error");
const val = parseInt(selectVal);
somaTotal = val; // RASS é pontuação direta do nível
dominiosValores.push({ nome: item.label, obtido: val });

// Alimentando palavras-chave para o NANDA
if (val >= 1 && val <= 4) diagnosticosKeywords.push("ansiedade", "agitação", "lesão", "violência");
else if (val === 0) diagnosticosKeywords.push("conhecimento", "conforto");
else if (val >= -3 && val <= -1) diagnosticosKeywords.push("ventilação", "mobilidade");
else if (val <= -4) diagnosticosKeywords.push("aspiração", "gases", "perfusão", "consciência");
}
});

if (incompleto) {
const msgErro = document.getElementById("msgValidacaoErro");
msgErro.style.display = "block";
if (primeiroErro) {
primeiroErro.scrollIntoView({ behavior: 'smooth', block: 'center' });
}
return;
}

document.getElementById("msgValidacaoErro").style.display = "none";
clearInterval(timerInterval);

// Determinar Classificação
const selectElement = document.getElementById("nivelRass");
const textoSelect = selectElement.options[selectElement.selectedIndex].text.replace(/^[+-]?\d+\s*-\s*/, "");

let bgPill = "";
let classe = "";
let recomendacao = "";

if (somaTotal >= 1 && somaTotal <= 4) {
bgPill = "#e11d48"; // Vermelho
classe = "Agitação";
recomendacao = "Il paziente è irrequieto o agitato. Richiede indagine sulla causa (es: dolore, ipossiemia) e aggiustamento della terapia sedativa/analgesica per la protezione del paziente.";
} else if (somaTotal === 0) {
bgPill = "#16a34a"; // Verde
classe = "Vigile e Calmo";
recomendacao = "Il paziente è in stato ideale di sedazione. Mantenere la strategia attuale ed effettuare il risveglio giornaliero secondo il protocollo dell'unità.";
} else if (somaTotal >= -3 && somaTotal <= -1) {
bgPill = "#eab308"; // Amarelo
classe = "Sedazione Leggera/Moderata";
recomendacao = "Il paziente risponde a stimoli verbali. Adeguato se l'obiettivo terapeutico richiede controllo ventilatorio, ma con preservazione di una certa coscienza.";
} else if (somaTotal <= -4) {
bgPill = "#e11d48"; // Vermelho
classe = "Sedazione Profonda / Coma";
recomendacao = "Il paziente non risponde a stimoli verbali, solo fisici o non risponde. Considerare la sospensione giornaliera della sedazione (se non controindicata) per rivalutazione neurologica.";
}

// Exibir no Hero Card
document.getElementById("scoreValor").textContent = somaTotal > 0 ? `+${somaTotal}` : somaTotal;
const pill = document.getElementById("statusPill");
pill.textContent = classe;
pill.style.backgroundColor = bgPill;

// Destacar card correspondente no Sidebar
const scpIds = ["scp-agitacao", "scp-alerta", "scp-sedacao-leve", "scp-coma"];
scpIds.forEach(id => {
const el = document.getElementById(id);
if (el) {
el.style.transform = "scale(1)";
el.style.boxShadow = "";
el.classList.remove("scp-highlight");
}
});

let scpAlvo = null;
if (somaTotal >= 1) scpAlvo = document.getElementById("scp-agitacao");
else if (somaTotal === 0) scpAlvo = document.getElementById("scp-alerta");
else if (somaTotal >= -3 && somaTotal <= -1) scpAlvo = document.getElementById("scp-sedacao-leve");
else if (somaTotal <= -4) scpAlvo = document.getElementById("scp-coma");

if (scpAlvo) {
scpAlvo.style.transform = "scale(1.03)";
scpAlvo.style.boxShadow = "0 8px 25px rgba(0,0,0,0.25)";
scpAlvo.classList.add("scp-highlight");
}

document.getElementById("resultadoMensagem").innerHTML = `<strong class="font-bold text-lg">${textoSelect}</strong><br><br><strong>Condotta:</strong> ${recomendacao}`;

// Gerar Tabela de Detalhamento
const tbody = document.getElementById("tabelaDominios");
tbody.innerHTML = "";
dominiosValores.forEach((dom) => {

const tr = document.createElement("tr");
tr.innerHTML = `
<td class="font-bold text-slate-700">${dom.nome}</td>
<td class="text-center font-black" style="color: ${bgPill}">${somaTotal > 0 ? '+'+somaTotal : somaTotal}</td>
<td>
<span class="text-[12px] font-bold px-3 py-1 rounded-full" style="background-color: ${bgPill}15; color: ${bgPill}; border: 1px solid ${bgPill}30">${textoSelect}</span>
</td>
`;
tbody.appendChild(tr);
});

// Mostrar Seção
resultadoSection.classList.add("visible");
resultadoSection.style.display = "block";
setTimeout(() => {
resultadoSection.scrollIntoView({ behavior: "smooth", block: "start" });
}, 100);

// Chamar NANDA
chamarNanda(diagnosticosKeywords);
}

async function chamarNanda(keywords) {
const lista = document.getElementById("lista-nanda");
lista.innerHTML = '<li class="text-sm text-slate-500 text-center py-4"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" class="fa-spin mr-2 inline-block" fill="currentColor" width="1em" height="1em" aria-hidden="true"><path d="M304 48a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zm0 416a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zM48 304a48 48 0 1 0 0-96 48 48 0 1 0 0 96zm464-48a48 48 0 1 0 -96 0 48 48 0 1 0 96 0zM142.9 437A48 48 0 1 0 75 369.1 48 48 0 1 0 142.9 437zm0-294.2A48 48 0 1 0 75 75a48 48 0 1 0 67.9 67.9zM369.1 437A48 48 0 1 0 437 369.1 48 48 0 1 0 369.1 437z"/></svg> Consultazione del database NANDA-I...</li>';

try {
const response = await fetch("/banco_nanda.json");
if (!response.ok) throw new Error("Errore di fetch");
const banco = await response.json();

const pontuados = banco
.map((diag) => {
let matchScore = 0;
const texto = (diag.diagnostico + " " + diag.definicao).toLowerCase();
keywords.forEach((kw) => {
if (texto.includes(kw.toLowerCase())) matchScore++;
});
return { ...diag, matchScore };
})
.filter((d) => d.matchScore > 0);

pontuados.sort((a, b) => b.matchScore - a.matchScore);

// Dedup
const prefixosIgnorar = ["rischio di", "disposizione a", "sindrome di", "tendenza a", "disposizione a", "rischio di"];
const temasUsados = new Set();
const topDiversos = [];

function extrairTema(titulo) {
let t = titulo.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
for (const p of prefixosIgnorar) {
if (t.startsWith(p)) { t = t.slice(p.length).trim(); break; }
}
const palavras = t.split(/\s+/).filter(w => w.length > 3 && !["para", "com", "sem", "como", "dos", "das", "que", "não", "nao", "melhorada", "melhorado", "prejudicada", "prejudicado", "adulto", "criança", "neonatal", "idoso", "lactente", "feminino", "masculino"].includes(w));
return palavras.slice(0, 4).join(" ");
}

for (const d of pontuados) {
const tema = extrairTema(d.diagnostico);
if (!temasUsados.has(tema) && !temasUsados.has(d.codigo)) {
temasUsados.add(tema);
temasUsados.add(d.codigo);
topDiversos.push(d);
}
if (topDiversos.length >= 6) break;
}

if (topDiversos.length > 0) {
lista.innerHTML = "";
topDiversos.forEach((d) => {
lista.innerHTML += `
<li class="nanda-item flex items-start gap-3">
<span class="bg-blue-100 text-blue-800 text-[10px] font-black px-2 py-1 rounded shadow-sm mt-0.5">${d.codigo}</span>
<div>
<h5 class="text-[13px] font-bold text-slate-800 leading-tight mb-1">${d.diagnostico}</h5>
<p class="text-[11px] text-slate-500 leading-snug m-0">${d.definicao}</p>
</div>
</li>
`;
});
} else {
lista.innerHTML = '<li class="text-xs text-slate-500 text-center py-4">Nessuna diagnosi critica primaria associata alle selezioni attuali.</li>';
}
} catch (e) {
lista.innerHTML = '<li class="text-xs text-red-500 text-center py-4">Database NANDA temporaneamente non disponibile.</li>';
}
}

function limpar() {
ITENS_RASS.forEach((item) => {
document.getElementById(item.id).value = "";
document.getElementById(`card_${item.id}`).classList.remove("error");

const badge = document.getElementById(`badge_${item.id}`);
const bar = document.getElementById(`bar_${item.id}`);
badge.textContent = `--/Punteggio`;
bar.style.width = `0%`;
bar.style.backgroundColor = "transparent";
});
document.getElementById("pacNome").value = "";
document.getElementById("pacIdade").value = "";
document.getElementById("pacSetor").value = "";
document.getElementById("msgValidacaoErro").style.display = "none";
atualizarBarraGlobal();

clearInterval(timerInterval);
timerInterval = null;
seconds = 0;
document.getElementById('crono-timer').textContent = "00:00";

const scpIds = ["scp-agitacao", "scp-alerta", "scp-sedacao-leve", "scp-coma"];
scpIds.forEach(id => {
const el = document.getElementById(id);
if (el) {
el.style.transform = "scale(1)";
el.style.boxShadow = "";
el.classList.remove("scp-highlight");
}
});

resultadoSection.classList.remove("visible");
window.scrollTo({ top: 0, behavior: "smooth" });
}

// --- EXPORTAÇÃO (PDF e PRINT) ---
function getDadosImpressao() {
let soma = 0;
ITENS_RASS.forEach((i) => {
const val = document.getElementById(i.id).value;
soma += val === "" ? 0 : parseInt(val);
});

let classe = "Vigile e Calmo";
if (soma >= 1 && soma <= 4) classe = "Agitação";
else if (soma >= -3 && soma <= -1) classe = "Sedazione Leggera/Moderata";
else if (soma <= -4) classe = "Sedazione Profonda / Coma";

const dataVal = document.getElementById("pacData").value;
const dataFormatada = dataVal ? dataVal.split("-").reverse().join("/") : new Date().toLocaleDateString("pt-BR");
const tempo = document.getElementById("crono-timer").textContent;

const selectElement = document.getElementById("nivelRass");
const textoSelect = selectElement.options[selectElement.selectedIndex].text.replace(/^[+-]?\d+\s*-\s*/, "");

return {
nome: document.getElementById("pacNome").value.trim(),
idade: document.getElementById("pacIdade").value.trim(),
setor: document.getElementById("pacSetor").value.trim(),
data: dataFormatada,
tempo: tempo,
soma: soma,
classe: classe,
desc: textoSelect
};
}

function gerarPDF() {
if (typeof window.jspdf === "undefined") {
const btn = document.getElementById("btnGerarPDF");
const origText = btn.innerHTML;
btn.innerHTML = "Caricamento generatore...";
btn.style.opacity = "0.7"; btn.style.pointerEvents = "none";
const s1 = document.createElement("script");
s1.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
document.body.appendChild(s1);
s1.onload = () => {
const s2 = document.createElement("script");
s2.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.2/jspdf.plugin.autotable.min.js";
document.body.appendChild(s2);
s2.onload = () => {
btn.innerHTML = origText;
btn.style.opacity = "1"; btn.style.pointerEvents = "auto";
executarPDF();
};
};
return;
}
executarPDF();
}

function executarPDF() {
const { jsPDF } = window.jspdf;
const doc = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
const data = getDadosImpressao();

const navy = [26, 62, 116];
const slateLight = [241, 245, 249];
const W = 210,
marginL = 18,
marginR = 18,
usable = W - marginL - marginR;

// Cabeçalho
doc.setFillColor(...navy);
doc.rect(0, 0, W, 32, "F");
doc.setTextColor(255, 255, 255);
doc.setFont("helvetica", "bold");
doc.setFontSize(14);
doc.text("Scala di Richmond (RASS)", marginL, 13);
doc.setFontSize(9);
doc.setFont("helvetica", "normal");
doc.text("Valutazione di Agitazione e Sedazione", marginL, 20);
doc.text("Data: " + data.data, W - marginR, 20, { align: "right" });

let y = 42;

// Identificação
if (data.nome || data.idade || data.setor) {
doc.setFillColor(...slateLight);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(...navy);
doc.setFont("helvetica", "bold");
doc.setFontSize(9);
doc.text("IDENTIFICAZIONE DEL PAZIENTE", marginL + 4, y + 5.5);
y += 12;

if (data.nome) {
doc.text("Nome:", marginL, y);
doc.setFont("helvetica", "normal");
doc.setTextColor(30, 41, 59);
doc.text(data.nome, marginL + 20, y);
y += 6;
doc.setFont("helvetica", "bold");
doc.setTextColor(...navy);
}
if (data.idade) {
doc.text("Idade:", marginL, y);
doc.setFont("helvetica", "normal");
doc.setTextColor(30, 41, 59);
doc.text(data.idade, marginL + 20, y);
y += 6;
doc.setFont("helvetica", "bold");
doc.setTextColor(...navy);
}
if (data.setor) {
doc.text("Setor/Leito:", marginL, y);
doc.setFont("helvetica", "normal");
doc.setTextColor(30, 41, 59);
doc.text(data.setor, marginL + 25, y);
y += 6;
}
y += 4;
}

// Pontuação Big
doc.setFillColor(...navy);
doc.roundedRect(marginL, y, usable, 22, 3, 3, "F");
doc.setTextColor(147, 197, 253);
doc.setFont("helvetica", "bold");
doc.setFontSize(8);
doc.text(`TEMPO DI VALUTAZIONE: ${data.tempo}`, W / 2, y + 6, { align: "center" });
doc.setTextColor(255, 255, 255);
doc.setFontSize(26);
doc.text(data.soma > 0 ? `+${data.soma}` : String(data.soma), W / 2, y + 17, { align: "center" });
y += 28;

// Status Pill
let pillColor = [22, 163, 74]; // Verde
if (data.soma >= 1) pillColor = [225, 29, 72]; // Vermelho
else if (data.soma >= -3 && data.soma <= -1) pillColor = [234, 179, 8]; // Amarelo
else if (data.soma <= -4) pillColor = [225, 29, 72]; // Vermelho

doc.setFillColor(...pillColor);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(255, 255, 255);
doc.setFont("helvetica", "bold");
doc.setFontSize(9);
doc.text(data.classe.toUpperCase(), W / 2, y + 5.5, { align: "center" });
y += 16;

// Tabela AutoTable
doc.setFillColor(...slateLight);
doc.roundedRect(marginL, y, usable, 8, 2, 2, "F");
doc.setTextColor(...navy);
doc.text("MEMORIA DELLA VALUTAZIONE CLINICA", marginL + 4, y + 5.5);
y += 11;

const bodyData = [
["Agitazione / Sedazione", data.soma > 0 ? `+${data.soma}` : String(data.soma), data.desc]
];

doc.autoTable({
startY: y,
margin: { left: marginL, right: marginR },
head: [["Criterio Valutato", "Score", "Comportamento"]],
body: bodyData,
foot: [["RESULTADO", data.soma > 0 ? `+${data.soma}` : String(data.soma), data.classe]],
styles: { fontSize: 9, cellPadding: 3, lineColor: [226, 232, 240], lineWidth: 0.3 },
headStyles: { fillColor: navy, textColor: 255, fontStyle: "bold" },
footStyles: { fillColor: [239, 246, 255], textColor: navy, fontStyle: "bold" },
columnStyles: { 0: { cellWidth: 45 }, 1: { halign: "center", cellWidth: 20 }, 2: { halign: "left" } },
alternateRowStyles: { fillColor: [248, 250, 252] },
});

// Rodapé
y = 280;
doc.setDrawColor(...slateLight);
doc.setLineWidth(0.3);
doc.line(marginL, y, W - marginR, y);
doc.setTextColor(148, 163, 184);
doc.setFontSize(7.5);
doc.setFont("helvetica", "normal");
doc.text("SESSLER, C. N. et al. Am J Respir Crit Care Med (2002).", marginL, y + 5);
doc.text("www.calculadorasdeenfermagem.com.br", W - marginR, y + 5, { align: "right" });

const nomeArquivo = data.nome ? `referto-rass-${data.nome.replace(/\s+/g, "-").toLowerCase()}.pdf` : "laudo-rass.pdf";
doc.save(nomeArquivo);
}

